SVM_DECISION_GUIDE = {
    "Use SVM when": {
        "Small to medium dataset": {
            "condition": "n < 10,000 samples",
            "reason": "SVM's O(n²-n³) training is manageable, often outperforms"
        },
        "High-dimensional features": {
            "condition": "d >> n  (more features than samples)",
            "reason": "SVM works well in high-D spaces; use linear kernel for text"
        },
        "Clear margin of separation": {
            "condition": "Classes are somewhat separable",
            "reason": "SVM explicitly maximizes this margin"
        },
        "No large training set available": {
            "condition": "n < 1,000 labeled examples",
            "reason": "Neural networks need much more data; SVM is effective with less"
        },
        "Text classification": {
            "condition": "TF-IDF features, LinearSVC",
            "reason": "Proven strong baseline for NLP before transformers"
        },
        "Bioinformatics": {
            "condition": "Gene expression, protein classification",
            "reason": "Many successful applications with specialized kernels"
        }
    },
    "Avoid SVM when": {
        "Very large dataset": {
            "condition": "n > 100,000",
            "reason": "Kernel SVM training is O(n²-n³) — use LinearSVC or XGBoost"
        },
        "Need feature importances": {
            "condition": "Business requires explanations",
            "reason": "SVM has no direct feature importances; use Random Forest"
        },
        "Noisy labels": {
            "condition": "Labels are unreliable",
            "reason": "SVM is sensitive to mislabeled support vectors"
        },
        "Multi-class with many classes": {
            "condition": "K > 10 classes",
            "reason": "OvO requires K(K-1)/2 models — expensive; use neural networks"
        },
        "Online learning required": {
            "condition": "Model must update incrementally",
            "reason": "SVM requires full retraining; use SGDClassifier instead"
        },
        "Native probabilities needed": {
            "condition": "Need calibrated probability outputs",
            "reason": "SVM needs Platt scaling post-hoc; use Logistic Regression"
        }
    }
}

