DROPOUT_STRATEGIES = {
    "Standard MLP Dropout": {
        "placement": "After each hidden layer's activation",
        "typical_p": "0.3 to 0.5",
        "code": "Linear → ReLU → Dropout(p=0.5) → Linear",
        "note": "Most common — effective for fully connected layers"
    },
    "Spatial Dropout (CNN)": {
        "placement": "Drop entire feature maps (channels), not individual pixels",
        "typical_p": "0.1 to 0.2",
        "code": "nn.Dropout2d(p=0.2)  # Zeros entire channels",
        "note": "Adjacent pixels in a feature map are correlated → drop whole map"
    },
    "Transformer Dropout": {
        "placement": "After attention weights AND after FFN sublayer",
        "typical_p": "0.1 (BERT, GPT use p=0.1)",
        "code": "attn_out = Dropout(p=0.1)(attn_out)",
        "note": "Lower p than MLP because Transformers are already regularized"
    },
    "Monte Carlo Dropout (Uncertainty)": {
        "placement": "Keep dropout ACTIVE at inference time",
        "typical_p": "Same as training p",
        "code": "model.train()  # Keep dropout ON at inference",
        "note": "Run N forward passes → variance of predictions = uncertainty estimate"
    },
    "DropPath / Stochastic Depth": {
        "placement": "Drop entire residual branches during training",
        "typical_p": "Linearly increasing from 0 to 0.2 with depth",
        "code": "Used in EfficientNetV2, DeiT, Swin Transformer",
        "note": "More effective than standard Dropout for vision Transformers"
    }
}

